insert into public.missions (id, category, teaser, title, body, locale, is_active)
values
  ('a1f2e3d4-c5b6-4789-a012-345678901109'::uuid, 'calm'::public.mission_category, 'Silence is not empty.', 'Mission: give your brain quiet', 'Sit or stand still for two minutes without a podcast, video, or feed. Hear the room. Let your mind drift without grabbing new input.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060001'::uuid, 'calm'::public.mission_category, 'A chair, a window, two quiet minutes.', 'Mission: window pause', 'Sit near a window or step outside. Spend two minutes watching light, shadow, or movement without naming tasks to do. When the two minutes are up, stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060002'::uuid, 'calm'::public.mission_category, 'Listen until you find the farthest sound.', 'Mission: distant listening', 'Stay still for one minute. Notice the closest sound you can hear, then the farthest. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060003'::uuid, 'calm'::public.mission_category, 'Your hands know this already.', 'Mission: warm mug', 'Hold a mug, cup, or glass with both hands. Notice its temperature and weight for 30 seconds. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060004'::uuid, 'calm'::public.mission_category, 'Find three shades of the same color.', 'Mission: color hunt', 'Look around the room or outside. Find three different shades of one color and let your eyes rest on each for a moment. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060005'::uuid, 'calm'::public.mission_category, 'Stand where you are and do less.', 'Mission: still feet', 'Stand or sit without adjusting your position for one minute. Feel where your body meets the floor, chair, or ground. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060006'::uuid, 'calm'::public.mission_category, 'Open a door. Not to leave.', 'Mission: fresh air moment', 'Open a window or step outside briefly. Take ten slow breaths while noticing the temperature of the air. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060007'::uuid, 'calm'::public.mission_category, 'One object deserves a closer look.', 'Mission: quiet inspection', 'Choose an ordinary object nearby. Spend two minutes noticing details you usually ignore. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060008'::uuid, 'calm'::public.mission_category, 'No destination. Just a slower pace.', 'Mission: slow walk', 'Walk for five minutes at a slightly slower pace than usual. Let your attention settle on your surroundings rather than your plans. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060009'::uuid, 'calm'::public.mission_category, 'The room has a soundtrack.', 'Mission: room orchestra', 'Pause whatever you''re doing. Listen for five different sounds in the space around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060010'::uuid, 'calm'::public.mission_category, 'Look up for thirty seconds.', 'Mission: ceiling and sky', 'Wherever you are, direct your gaze upward. Notice shapes, textures, clouds, beams, or branches overhead. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060011'::uuid, 'calm'::public.mission_category, 'Nothing to solve for the next minute.', 'Mission: one-minute drift', 'Sit comfortably and let your thoughts wander for sixty seconds. No notes, no plans, no corrections. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060012'::uuid, 'calm'::public.mission_category, 'Find the softest thing nearby.', 'Mission: texture break', 'Touch a fabric, leaf, blanket, or other surface. Spend a minute noticing its texture without rushing. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060013'::uuid, 'calm'::public.mission_category, 'A tiny reset hides in plain sight.', 'Mission: tidy one spot', 'Clear or straighten a space no larger than a dinner plate. Pause and look at it when you''re done. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060014'::uuid, 'calm'::public.mission_category, 'The weather has a detail for you.', 'Mission: weather notice', 'Step outside or look through a window. Identify one thing the weather is doing right now. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060015'::uuid, 'calm'::public.mission_category, 'Try a quieter version of a routine.', 'Mission: silent sip', 'Have a drink of water, tea, or coffee without reading, watching, or multitasking. Pay attention only to the experience. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060016'::uuid, 'calm'::public.mission_category, 'One corner of the world, fully noticed.', 'Mission: corner study', 'Choose a small corner of a room, yard, porch, or street view. Observe it for two minutes as if seeing it for the first time. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060017'::uuid, 'calm'::public.mission_category, 'Borrow calm from a tree or a wall.', 'Mission: lean and pause', 'Lean against something steady: a wall, fence, railing, or tree. Stay there for one minute and feel the support beneath you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060018'::uuid, 'calm'::public.mission_category, 'There is a rhythm nearby.', 'Mission: find a pattern', 'Listen or look for something repeating: footsteps, wind, a clock, distant traffic, birdsong. Follow that pattern for a minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060019'::uuid, 'calm'::public.mission_category, 'A seat with no agenda.', 'Mission: sit outside', 'If you can, sit outdoors for five minutes. Let the environment come to you instead of seeking stimulation. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060020'::uuid, 'calm'::public.mission_category, 'One deep exhale changes the pace.', 'Mission: longer exhale', 'Take five slow breaths. Let each exhale last a little longer than the inhale. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060021'::uuid, 'calm'::public.mission_category, 'Watch movement you didn''t create.', 'Mission: moving world', 'Spend two minutes observing something in motion: leaves, clouds, shadows, water, people, or animals. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060022'::uuid, 'calm'::public.mission_category, 'The next minute belongs to your senses.', 'Mission: sensory check-in', 'Notice one thing you can see, hear, feel, and smell. Move slowly through each sense. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060023'::uuid, 'calm'::public.mission_category, 'A quiet view is waiting somewhere nearby.', 'Mission: change vantage point', 'Move to a different seat, doorway, porch, or patch of ground. Spend three minutes taking in the view from there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060025'::uuid, 'calm'::public.mission_category, 'Find the calmest sound around you.', 'Mission: sound anchor', 'Choose one steady sound and keep your attention on it for sixty seconds. When your mind wanders, gently return. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060026'::uuid, 'calm'::public.mission_category, 'Rest your eyes farther away.', 'Mission: long-distance gaze', 'Look toward the horizon, a distant building, a field, or the far end of a street. Keep your gaze there for a minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060027'::uuid, 'calm'::public.mission_category, 'A pause between tasks can be a place.', 'Mission: doorway pause', 'Before entering your next room or activity, stop in the doorway for ten seconds. Notice where you are before moving on. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060028'::uuid, 'calm'::public.mission_category, 'Notice what is already supporting you.', 'Mission: points of contact', 'Sit or stand comfortably. Spend a minute noticing every place your body touches something else. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060029'::uuid, 'calm'::public.mission_category, 'The world keeps moving without instructions.', 'Mission: watch and wait', 'Choose a spot outdoors or by a window. Observe whatever passes through it for three minutes without judging or tracking time. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060030'::uuid, 'calm'::public.mission_category, 'One small pocket of quiet.', 'Mission: close your eyes', 'Close your eyes for thirty seconds in a safe place. Listen carefully and notice what arrives when sight steps back. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901110'::uuid, 'learning'::public.mission_category, 'One skill, tiny step.', 'Mission: micro-practice', 'Pick something you’ve wanted to learn. Do exactly one tiny practice — one chord, one sentence, one stretch, one line read aloud. Stop after that one step.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070001'::uuid, 'learning'::public.mission_category, 'Borrow one word from a different world.', 'Mission: learn a new word', 'Ask someone, read a sign, or open a book to find one word you don''t know well. Learn what it means and say it out loud once. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070002'::uuid, 'learning'::public.mission_category, 'Your memory gets one small challenge today.', 'Mission: remember three', 'Look around and choose three objects. Study them for 30 seconds, then turn away and recall as many details as you can. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070003'::uuid, 'learning'::public.mission_category, 'Steal a tiny skill from someone nearby.', 'Mission: ask how', 'Find someone you can talk to and ask how they do a simple task well. Listen without interrupting. Thank them and stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070004'::uuid, 'learning'::public.mission_category, 'Ten minutes with a thing you''ve never noticed.', 'Mission: inspect an object', 'Choose an everyday object and examine it closely. Notice marks, materials, or features you''ve never paid attention to before. Stop after five minutes if you like.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070005'::uuid, 'learning'::public.mission_category, 'Teach your future self one fact.', 'Mission: leave a note', 'Learn one new fact from a book, label, conversation, or sign. Write it on a scrap of paper in your own words. That''s enough for today.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070006'::uuid, 'learning'::public.mission_category, 'A sound is waiting to be identified.', 'Mission: name that sound', 'Spend two minutes listening. Pick one sound you can''t immediately place and investigate what makes it. Stop once you''ve learned something new.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070007'::uuid, 'learning'::public.mission_category, 'One sentence can become a lesson.', 'Mission: summarize a page', 'Read a single page from any book, magazine, or leaflet. Capture its main idea in one sentence from memory. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070008'::uuid, 'learning'::public.mission_category, 'There''s a skill hiding in your hands.', 'Mission: switch hands', 'Do one simple task with your non-dominant hand: stirring, brushing, opening a drawer, or similar. Notice what feels different. Stop after a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070009'::uuid, 'learning'::public.mission_category, 'Learn the name of something living.', 'Mission: identify a neighbor', 'Find a tree, flower, bird, or plant nearby. Learn its name from a sign, a book, or someone who knows. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070010'::uuid, 'learning'::public.mission_category, 'One question. One real answer.', 'Mission: ask an elder', 'Talk with someone older than you, if available. Ask what skill they used to rely on a lot in the past but use much less today. Listen to their answer without interrupting. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070011'::uuid, 'learning'::public.mission_category, 'A map you already know has a gap in it.', 'Mission: redraw a route', 'From memory, sketch the route to a place you visit often. Compare it to reality the next time you travel it. Stop after the sketch.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070012'::uuid, 'learning'::public.mission_category, 'Can you explain it in one breath?', 'Mission: explain simply', 'Choose something you know well. Explain it out loud as if speaking to a curious twelve-year-old. Stop when you reach one minute.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070013'::uuid, 'learning'::public.mission_category, 'Your eyes know more than you think.', 'Mission: spot five patterns', 'Walk through a room, street, garden, or field. Find five repeating shapes, colors, or textures. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070014'::uuid, 'learning'::public.mission_category, 'Borrow a phrase from another language.', 'Mission: learn a phrase', 'Ask someone or look up a simple greeting in a language you don''t speak. Say it three times. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070015'::uuid, 'learning'::public.mission_category, 'A label can teach more than it seems.', 'Mission: read the fine print', 'Pick an item in your home and read the small print you usually ignore. Learn one detail about where it came from or how it''s made. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070016'::uuid, 'learning'::public.mission_category, 'Today, practice noticing cause and effect.', 'Mission: follow a chain', 'Observe something happening around you. Trace it back through three possible causes. Stop once you''ve built the chain.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070017'::uuid, 'learning'::public.mission_category, 'Learn one thing a place is trying to tell you.', 'Mission: read a sign', 'Find a public sign, notice board, or information plaque. Read it slowly and remember one detail. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070018'::uuid, 'learning'::public.mission_category, 'Your voice can be a study tool.', 'Mission: repeat and recall', 'Read a short paragraph aloud. Put it away and repeat the main idea from memory. Stop after one attempt.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070019'::uuid, 'learning'::public.mission_category, 'A stranger''s expertise might be nearby.', 'Mission: ask one question', 'If you meet someone working on a task today, ask a respectful question about it. Learn one thing you didn''t know before. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070020'::uuid, 'learning'::public.mission_category, 'Turn observation into a tiny field study.', 'Mission: count something', 'Choose something visible around you—birds, parked vehicles, fence posts, clouds, or footsteps. Count for two minutes and notice any pattern. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070021'::uuid, 'learning'::public.mission_category, 'One recipe, tool, or object has a history.', 'Mission: trace an origin', 'Pick an everyday item nearby. Learn where it was made or where the idea came from. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070022'::uuid, 'learning'::public.mission_category, 'Practice a skill for less time than you think.', 'Mission: two-minute practice', 'Spend exactly two minutes on a skill you already care about: drawing, singing, balancing, handwriting, or another favorite. Stop when the timer ends.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070023'::uuid, 'learning'::public.mission_category, 'Memory likes details more than effort.', 'Mission: notice three details', 'Look at a photograph, painting, or view outside. Find three details you missed at first glance. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070024'::uuid, 'learning'::public.mission_category, 'A household object has instructions worth reading.', 'Mission: learn a function', 'Choose a tool, appliance, or gadget you already own. Discover one feature you''ve never used or understood. Stop after learning it.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070025'::uuid, 'learning'::public.mission_category, 'Learn by comparing, not collecting facts.', 'Mission: find a difference', 'Place two similar objects side by side. Compare them carefully and list three differences. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070026'::uuid, 'learning'::public.mission_category, 'There''s a lesson in the weather today.', 'Mission: read the sky', 'Step outside or look through a window. Notice the clouds, light, or wind and make one prediction about the next hour. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070027'::uuid, 'learning'::public.mission_category, 'Learn a name, not just a face.', 'Mission: remember someone', 'If you meet someone today, make a deliberate effort to remember their name. Repeat it once in conversation. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070028'::uuid, 'learning'::public.mission_category, 'One forgotten fact is waiting on a shelf.', 'Mission: open a reference', 'Pick up a dictionary, handbook, guide, or reference book if you have one nearby. Open to a random page and learn one thing. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070029'::uuid, 'learning'::public.mission_category, 'Make a prediction before you know.', 'Mission: guess first', 'Before checking an answer, estimate it: distance, age, quantity, or time. Then compare your guess with reality. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070030'::uuid, 'learning'::public.mission_category, 'Learn something from where you already are.', 'Mission: study the room', 'Pause wherever you are. Find one object, one sound, and one texture you''ve overlooked until now. Stop after noticing all three.', 'en', true)
